<script setup lang="ts">
import {onBeforeUnmount,ref,watch} from 'vue'
import AppModal from './AppModal.vue'
import {request} from '@/services/quality'
const props=defineProps<{version:number;hasLogo?:boolean;admin:boolean}>();const emit=defineEmits<{saved:[]}>();const url=ref('');const open=ref(false);const remove=ref(false);const busy=ref(false);const error=ref('');const file=ref<File|null>(null)
function headers(){return {Authorization:'Bearer '+sessionStorage.getItem('bestpharma.token'),'X-Officine-ID':sessionStorage.getItem('bestpharma.officine')||''}}
function clear(){if(url.value)URL.revokeObjectURL(url.value);url.value=''}
let generation=0
async function load(){const current=++generation;clear();if(!props.hasLogo)return;try{const r=await fetch('/api/v1/officine/logo',{headers:headers()});if(!r.ok)throw new Error('Logo indisponible.');const blob=await r.blob();if(current===generation)url.value=URL.createObjectURL(blob)}catch(e){if(current===generation)error.value=(e as Error).message}}
watch(()=>[props.version,props.hasLogo],load,{immediate:true});onBeforeUnmount(()=>{generation++;clear()})
function edit(deleting=false){remove.value=deleting;file.value=null;error.value='';open.value=true}
async function save(){busy.value=true;error.value='';try{if(remove.value)await request('/officine/logo','DELETE',{profile_version:props.version});else{const body=new FormData();body.append('profile_version',String(props.version));body.append('file',file.value!);const r=await fetch('/api/v1/officine/logo',{method:'POST',headers:{...headers(),Accept:'application/json'},body});const d=await r.json();if(!r.ok)throw new Error(Object.values(d.errors||{}).flat().join(' ')||d.message||'Enregistrement impossible.')}open.value=false;emit('saved')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><div class="section-toolbar"><div><img v-if="url" :src="url" alt="Logo de l’officine" style="max-width:140px;max-height:100px;object-fit:contain"/><span v-else class="page-subtitle">Aucun logo affiché</span><p v-if="error&&!open" class="alert error" role="alert">{{error}}</p></div><div v-if="admin" class="module-links"><button class="button secondary small" @click="edit()">{{hasLogo?'Remplacer le logo':'Ajouter un logo'}}</button><button v-if="hasLogo" class="button secondary small" @click="edit(true)">Retirer le logo</button></div></div><AppModal v-model="open" :title="remove?'Retirer le logo ?':'Logo de l’officine'" :busy="busy"><form id="office-logo" class="form-body correction-form" @submit.prevent="save"><p v-if="error" class="alert error" role="alert">{{error}}</p><p v-if="remove">Le logo sera retiré de la fiche. Les autres informations seront conservées.</p><template v-else><label>Image PNG ou JPEG<input type="file" accept="image/png,image/jpeg" required @change="file=($event.target as HTMLInputElement).files?.[0]||null"/></label><p>2 Mo maximum, 2 000 × 2 000 pixels maximum. Le serveur réencode l’image en PNG et retire ses métadonnées. Stockage privé ; pas d’analyse antivirus.</p></template></form><template #footer><button class="button secondary" :disabled="busy" @click="open=false">Annuler</button><button class="button primary" :disabled="busy||(!remove&&!file)" form="office-logo" type="submit">Confirmer</button></template></AppModal></template>
